CustomField.formula:
IF ( TEXT ( Cancel_Record__c  ) = 'Upper', '⚠️',
IF ( TEXT ( Cancel_Record__c ) = 'Own', '❌',
IF ( TEXT ( Stage__c ) = 'Delayed(Start)' || TEXT ( Stage__c ) = 'Delayed(End)', '🔴',
